"""Ausstattungs-Bezeichnungen in den 24 EU-Amtssprachen.
ERZEUGT von scripts/i18n/ausstattung-katalog-erzeugen.py —
NICHT von Hand bearbeiten. Die Quelle sind die Namensräume
`amenities`, `eigeneAusstattung` und `roomAmenities` in
`web/messages/<sprache>.json`; dort wird gepflegt.

Warum der Server diese Labels führt und nicht der Renderer:
siehe den Kopf des Generators. Kurz: der Renderer, die
Gast-Mail und der Marktplatz brauchen dieselben Texte, und
jede App mit eigener Kopie ist eine Stelle, die beim
nächsten neuen Merkmal vergessen wird.
"""

